// AC: @session-model-evolution ac-6
describe("kspec session log list session type display (CLI)", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();

    const sessionsDir = path.join(tempDir, "sessions");
