    26→/**
    27→ * Perform session checkpoint - check for uncommitted work before ending session.
    28→ *
    29→ * This is designed for use as a Claude Code stop hook. It checks for:
    30→ * - Uncommitted git changes (staged, unstaged, untracked)
    31→ * - Tasks in in_progress status
    32→ * - Incomplete todos on active tasks
    33→ *
    34→ * Returns a structured result indicating whether the session can end cleanly.
    35→ */
    36→export async function performCheckpoint(
    37→  ctx: KspecContext,
    38→  options: CheckpointOptions,
    39→): Promise<CheckpointResult> {
    40→  const issues: CheckpointIssue[] = [];
    41→  const instructions: string[] = [];
    42→
    43→  // Load tasks
    44→  const allTasks = await loadAllTasks(ctx);
    45→  const allItems = await loadAllItems(ctx);
    46→  const refIndex = new ReferenceIndex(allTasks, allItems);
    47→
    48→  // Filter in-progress tasks by session scope
    49→  // AC: @cmd-session-checkpoint ac-session-scope
    50→  // AC: @cmd-session-checkpoint ac-no-session-scope
    51→  // AC: @cmd-session-checkpoint ac-session-failsafe
    52→  const sessionId = process.env.KSPEC_SESSION_ID || null;
    53→  const sessionActiveCache = new Map<string, boolean>();
    54→  async function isSessionActive(sid: string): Promise<boolean> {
    55→    if (sessionActiveCache.has(sid)) return sessionActiveCache.get(sid)!;
    56→    const session = await getSession(ctx.sessionsDir, sid);
    57→    // Fail-safe: if lookup fails (null), treat as NOT active → include task
    58→    const active = session?.status === "active";
    59→    sessionActiveCache.set(sid, active);
    60→    return active;
    61→  }
    62→
    63→  const inProgressTasks = [];
    64→  for (const t of allTasks) {
    65→    if (t.status !== "in_progress") continue;
    66→    if (!t.session_id) {
    67→      // Unclaimed — always include
    68→      inProgressTasks.push(t);
    69→    } else if (t.session_id === sessionId) {
    70→      // Mine — always include
    71→      inProgressTasks.push(t);
    72→    } else if (!(await isSessionActive(t.session_id))) {
    73→      // Owning session is gone/closed/corrupt — include (orphaned)
    74→      inProgressTasks.push(t);
    75→    }
