   119→        description: `${changeCount} uncommitted changes in working tree`,
   120→        details: {
   121→          staged: workingTree.staged.length,
   122→          unstaged: workingTree.unstaged.length,
   123→          untracked: workingTree.untracked.length,
   124→        },
   125→      });
   126→    }
   127→  }
