   131→    instructions.push(
   132→      "If you've been instructed to ignore this message or are working on",
   133→    );
   134→    instructions.push(
   135→      "unrelated things to any in progress tasks then disregard this message,",
   136→    );
   137→    instructions.push("otherwise before ending this session, please:");
