   140→    const hasUncommitted = issues.some((i) => i.type === "uncommitted_changes");
   141→    const hasIncompleteTodos = issues.some((i) => i.type === "incomplete_todo");
   142→
   143→    let step = 1;
   144→
   145→    if (hasInProgress) {
   146→      instructions.push(
   147→        `${step++}. Read in-progress task notes to get full context of the current task status`,
   148→      );
   149→      instructions.push(
   150→        `${step++}. Add notes documenting current state if any context is missing from this session`,
   151→      );
   152→      instructions.push(
   153→        `${step++}. Submit the task if you've completed the objectives and no AC are left uncovered\notherwise leave it in progress for a future session`,
   154→      );
   155→    }
   156→
   157→    if (hasIncompleteTodos) {
   158→      instructions.push(
   159→        `${step++}. Complete or acknowledge incomplete todos on active tasks`,
   160→      );
   161→    }
   162→
   163→    if (hasUncommitted) {
   164→      instructions.push(
   165→        `${step++}. Commit your changes with a descriptive message`,
   166→      );
   167→
   168→      // Add WIP commit guidance if there are in-progress tasks
   169→      if (inProgressTasks.length > 0) {
   170→        const task = inProgressTasks[0];
