   172→        instructions.push("");
   173→        instructions.push("Suggested WIP commit:");
   174→        instructions.push(`  ${guidance.message}`);
   175→        instructions.push("");
   176→        for (const trailer of guidance.trailers) {
   177→          instructions.push(`  ${trailer}`);
   178→        }
   179→      }
   180→    }
   181→
   182→    instructions.push("");
   183→    instructions.push("Use: kspec task @task to get current task state");
   184→    instructions.push(
   185→      'Use: kspec task note @task "Progress notes..." to document state',
   186→    );
   187→    instructions.push(
   188→      "Use: kspec task submit @task if task is done",
   189→    );
   190→  }
   191→
   192→  // Allow stop if:
   193→  // - No issues found
   194→  // - --force flag passed
