    const dest = path.join(tempDir, entry.name);
    if (entry.isDirectory()) {
      await fs.cp(source, dest, { recursive: true });
    } else {
      await fs.copyFile(source, dest);
    }
  }

  // Create sessions dir
  const sessionsDir = path.join(tempDir, '.kspec-sessions');
  await fs.mkdir(sessionsDir, { recursive: true });

  // Create a session
  const sessionId = '01ABCDEFGHJKMNPQRSTV0001';
  const sessionDir = path.join(sessionsDir, sessionId);
  await fs.mkdir(sessionDir, { recursive: true });
  await fs.writeFile(path.join(sessionDir, 'session.yaml'), 'id: ' + sessionId + '\nagent_type: test\nstatus: active\nstarted_at: \"2026-01-01T00:00:00.000Z\"\n');

  console.log('tempDir:', tempDir);
  console.log('sessionsDir:', sessionsDir);
  console.log('session exists:', await fs.access(path.join(sessionDir, 'session.yaml')).then(() => true).catch(() => false));

  // Run initContext
  const { spawnSync } = require('child_process');
  const r = spawnSync('node', [path.join(__dirname, 'dist', 'cli', 'index.js'), 'session', 'checkpoint', '--json'], {
