    encoding: 'utf-8',
    env: { ...process.env, KSPEC_SESSION_ID: sessionId, KSPEC_AUTHOR: '@test' },
  });

  console.log('stdout:', r.stdout);
  console.log('stderr:', r.stderr);
  console.log('exit:', r.status);

  await fs.rm(tempDir, { recursive: true });
}

test().catch(console.error);
